import {accessPreferences,aacChoices,aacEffect,scanStep,gamepadCommands,freshCommands,requestHaptic} from './access.js';
export function mountAdaptiveAccess({settings,save,open,close,button,paragraph,content,panel,notify,navigate,setPaused,speak,solarMessage,helper}){
 let feedbackKind='notice';let prefs=accessPreferences(settings.access),index=0,elapsed=0,previous=0,signature='',padState=[],controllerPad=null,focusSource=null;
 const caption=document.createElement('p');caption.id='live-caption';caption.setAttribute('role','region');caption.setAttribute('aria-label','Game captions');caption.hidden=!prefs.captions;document.querySelector('main').append(caption);
 const notification=document.createElement('p');notification.id='visual-alert';notification.setAttribute('role','region');notification.setAttribute('aria-label','Visual notifications');notification.hidden=true;document.querySelector('main').append(notification);
 const feedback=document.createElement('div');feedback.id='access-feedback';feedback.append(caption,notification);document.querySelector('#stage').append(feedback);
 const persist=()=>{settings.access={...prefs};apply();return save()};
 function apply(){document.documentElement.classList.toggle('dim-world',prefs.dimWorld);const useNotice=feedbackKind==='notice'&&prefs.visualAlerts;caption.hidden=!prefs.captions||useNotice;notification.hidden=!useNotice||!notification.textContent;feedback.hidden=caption.hidden&&notification.hidden||!caption.textContent;}
 function output(message,kind='notice'){feedbackKind=kind;caption.textContent=message;notification.textContent=message;apply();}
 function controls(){const root=panel.open?panel:document;return [...root.querySelectorAll('button,input,select')].filter(e=>!e.disabled&&e.getClientRects().length&&!e.closest('[hidden]')&&(e.closest('#panel')||!panel.open));}
 function focusAt(delta=0){const list=controls();if(!list.length)return;const nextSignature=list.map(e=>e.id||e.getAttribute('aria-label')||e.textContent).join('|');if(nextSignature!==signature){signature=nextSignature;index=0;elapsed=0;}index=scanStep(index,list.length,delta);document.querySelectorAll('.adaptive-focus').forEach(e=>e.classList.remove('adaptive-focus'));list[index].classList.add('adaptive-focus');list[index].focus({preventScroll:false});return list[index];}
 function command(action){focusSource=action;if(action==='aac'){aac();return}if(action==='help'){helper();return}if(action==='back'){if(panel.open)close();return}if(action==='next'||action==='previous'){focusAt(action==='next'?1:-1);elapsed=0;return}if(action==='select'){const e=focusAt();if(!e)return;if(e.matches('input[type=range]')){e.value=+e.value>=+e.max?e.min:Math.min(+e.max,+e.value+(+e.step||1));e.dispatchEvent(new Event('input',{bubbles:true}));}else e.click();elapsed=0;}}
 function aac(page=0){open('My words');paragraph('Choose what I want to say or do. Help requests are shown here for someone nearby.');const grid=document.createElement('div');grid.className='aac-grid';content.append(grid);for(const c of aacChoices.slice(page*4,page*4+4))button(c.icon+' '+c.text,()=>choose(c.id),grid);if(page>0)button('← Previous words',()=>aac(page-1));if(aacChoices.length>(page+1)*4)button('More words →',()=>aac(page+1));button('♿ Access options',options);button('↩ Back to activity',close);}
 function choose(id){const effect=aacEffect(id);if(!effect)return;if(effect.mute){settings.volume=0;if('speechSynthesis'in window)speechSynthesis.cancel();}if(effect.dim)prefs.dimWorld=true;if(effect.pause)setPaused(true);if(effect.save){const ok=persist();message(effect.text,ok?'Saved on this device.':'Saving is unavailable here. Please keep this session open.');return}persist();if(effect.target){close();setPaused(false);navigate(effect.target);notify(effect.future?solarMessage:effect.text);if(prefs.aacVoice)speak(effect.text);return}message(effect.text,effect.pause?'The game is paused. This request stays visible for someone nearby.':effect.dim?'Scenery dimmed. You can change it in Access options.':'Sound muted. You can change volume in Settings.');}
 function message(phrase,detail){open(phrase);paragraph(phrase,'aac-phrase');paragraph(detail);output(phrase+'. '+detail);if(prefs.aacVoice&&settings.volume>0)speak(phrase);button('🔊 Say it again',()=>{output(phrase);if(settings.volume>0)speak(phrase)});button('My words',()=>aac());button('▶ Return to game',()=>{close();setPaused(false)});}
 function options(){open('Adaptive access');paragraph('Switches use keyboard signals from a compatible interface. One-switch: Space selects while scanning. Two-switch: Space advances; Enter selects.');
 for(const [key,label,values]of [['switchMode','Switch access',['off','one','two']],['scanMs','Scan interval',[1000,2000,3000,5000,8000,12000]]])button(label+': '+(key==='scanMs'?prefs[key]/1000+' seconds':prefs[key]),()=>{prefs[key]=values[(values.indexOf(prefs[key])+1)%values.length];elapsed=0;persist();options()});
 for(const [key,label]of [['captions','Game speech captions'],['visualAlerts','Visual alerts'],['haptics','Haptic feedback'],['aacVoice','Speak my AAC choices'],['dimWorld','Dim scenery'],['controller','Controller input']]){const l=document.createElement('label'),input=document.createElement('input');input.type='checkbox';input.checked=prefs[key];input.onchange=()=>{prefs[key]=input.checked;persist()};l.append(input,document.createTextNode(label));content.append(l)}
 for(const [key,label]of [['nextKey','Next / one-switch key'],['selectKey','Two-switch select key']]){const b=button(label+': '+(prefs[key]===' '?'Space':prefs[key]),()=>{b.textContent='Press a key to bind (Escape cancels)';const capture=e=>{e.preventDefault();e.stopImmediatePropagation();document.removeEventListener('keydown',capture,true);if(e.key!=='Escape'&&e.key!==prefs[key==='nextKey'?'selectKey':'nextKey']){prefs[key]=e.key;persist();}options()};document.addEventListener('keydown',capture,true)});}
 paragraph(controllerPad?'Standard controller detected.':'No standard controller detected yet. Press a controller button to connect it.');button('Read last caption / notice',()=>{const text=caption.textContent;open('Last game message');paragraph(text||'No game message yet.');button('🔊 Listen',()=>speak(text));button('Access options',options)});button('Reset input keys',()=>{prefs.nextKey=' ';prefs.selectKey='Enter';persist();options()});button('📍 Choose a destination',destinations);button('🤖 PIP helper',helper);paragraph('Standard controller: D-pad/stick moves focus, A selects, B closes, X opens My words, Y opens Help. Haptics depend on your device. Captions cover game speech, not room conversations.');}
 function destinations(){open('Choose a destination');helper('destinations');}
 document.addEventListener('keydown',e=>{if(e.repeat){if(prefs.switchMode!=='off'&&[prefs.nextKey,prefs.selectKey].includes(e.key))e.preventDefault();return;}const editing=e.target.matches('input:not([type=checkbox]):not([type=range]),textarea');if(editing)return;if(prefs.switchMode!=='off'&&e.key===prefs.nextKey){e.preventDefault();command(prefs.switchMode==='one'?'select':'next')}else if(prefs.switchMode!=='off'&&e.key===prefs.selectKey){e.preventDefault();command('select')}});
 document.addEventListener('click',e=>{if(e.target.closest('button,input,select'))requestHaptic(prefs.haptics,controllerPad)});
 function frame(t){const dt=Math.min(t-previous,100);previous=t;if(!document.hidden){if(prefs.switchMode==='one'){if(!document.querySelector('.adaptive-focus'))focusAt();elapsed+=dt;if(elapsed>=prefs.scanMs){command('next');elapsed=0;}}if(prefs.controller){let pad;try{pad=[...(navigator.getGamepads?.()||[])].find(p=>p?.mapping==='standard'&&p.connected)}catch{}controllerPad=pad;const now=gamepadCommands(pad);const fresh=freshCommands(now,padState);if(fresh.length)command(fresh[0]);padState=now;}else padState=[];}requestAnimationFrame(frame)}
 const nav=document.querySelector('nav');for(const [id,label,fn]of [['aac','💬 My words',()=>aac()],['access','♿ Access',options]]){const b=document.createElement('button');b.id=id;b.textContent=label;b.onclick=fn;nav.append(b)}
 const inPanel=document.createElement('button');inPanel.id='panel-aac';inPanel.textContent='💬 My words';inPanel.onclick=()=>aac();panel.insertBefore(inPanel,document.querySelector('#content'));
 function resetFocus(){index=0;elapsed=0;signature='';document.querySelectorAll('.adaptive-focus').forEach(e=>e.classList.remove('adaptive-focus'));}
 apply();requestAnimationFrame(frame);return {output,aac,options,command,resetFocus,get preferences(){return prefs}};
}
